#region SupplyStationV3
const string VERSION="3.2.4";/**SupplyStationV3 Script v3.2.4*Protocol:v3(PMV4 integration)**The dispatcher.Evaluates exchange requests,picks the right drone,*loads outbound cargo via PMV4,and dispatches.Unloads drones on return.*Outbound manifests are clamped to the drone's cargo volume, split*fairly across items so one oversized item can't starve the rest.**Version History:*3.2.4-LCDs on subgrids(rotor/hinge/piston)now display;scan not limited to PB grid*3.2.3-LCDs tagged after compile auto-appear(~10s rescan);no RELOAD needed*3.2.2-Outbound/Inbound totals count only the matching mission leg;fix drone total*3.2.1-Fix crossed wires:EXCHANGE_ACCEPTED now carries target OrderStation ID*3.2.0-HOLD/RESUME commands:pause dispatch,in-flight missions finish*3.1.0-Outbound manifest capacity clamp+fair-fill,DroneFillFactor,ASSIGN_NACK unwind,docked-home sweep*3.0.1-Sloped LCD rotation fix;SS_INVENTORY broadcasts deficit-mode exchangeable amounts*3.0.0-Initial v3 release:dispatcher model,SAM Advertiser connectors,home-connector reservations*/const string CH_PMV4_INV="PMV4_INVENTORY";const string CH_PMV4_CMD="PMV4_CARGO_CMD";const string CH_PMV4_STAT="PMV4_CARGO_STATUS";const string CH_EXCHANGE_REQ="EXCHANGE_REQUEST";const string CH_EXCHANGE_ACC="EXCHANGE_ACCEPTED";const string CH_EXCHANGE_REJ="EXCHANGE_REJECTED";const string CH_MISSION_COMPLETE="MISSION_COMPLETE";const string CH_SS_INVENTORY="SS_INVENTORY";const string CH_DRONE_AVAILABLE="DRONE_AVAILABLE";const string CH_DRONE_ASSIGN="DRONE_ASSIGN";const string CH_DRONE_ARRIVED="DRONE_ARRIVED";const string CH_DRONE_NACK="DRONE_NACK";const string CH_STATION_STATUS="STATION_STATUS";const string CH_SAM="SAM";const string MS_LOADING="LOADING";const string MS_OUTBOUND="OUTBOUND";const string MS_AT_DEST="AT_DEST";const string MS_RETURNING="RETURNING";const string MS_UNLOADING="UNLOADING";class ActiveMission{public string OrderStationId;public string DroneId;public string DroneGridName;public string Destination;public string HomeConnector;public Vector3D DestinationGPS;public Dictionary<string,int>WillBring=new Dictionary<string,int>();public Dictionary<string,int>WillCollect=new Dictionary<string,int>();public string State;public int DispatchTick;}class DroneInfo{public string DroneId;public string HomeStation;public string CurrentStation;public string GridName;public List<string>Tags=new List<string>();public double CargoCapacityL;public int LastSeenTick;}string stationId="";string exchangeMode="deficit";double droneSpeedMS=100.0;double droneFillFactor=0.95;string oreIngotTag="[PMO]";string mixedTag="[PMX]";Dictionary<string,int>oreReserves=new Dictionary<string,int>();Dictionary<string,int>ownOreInventory=new Dictionary<string,int>();int oreScanCounter=0;const int ORE_SCAN_INTERVAL_TICKS=6;int panelRescanCounter=0;const int PANEL_RESCAN_INTERVAL_TICKS=6;struct ThemeColors{public Color BG,HDR,LBL,VAL,GOOD,WARN,CRIT,DIM;}static ThemeColors ThemeDefault(){return new ThemeColors{BG=new Color(8,8,18),HDR=new Color(0,210,210),LBL=new Color(0,160,160),VAL=new Color(200,200,215),GOOD=new Color(0,210,90),WARN=new Color(255,185,0),CRIT=new Color(255,55,55),DIM=new Color(35,40,50)};}static ThemeColors ThemeMilitary(){return new ThemeColors{BG=new Color(10,12,8),HDR=new Color(180,190,100),LBL=new Color(140,150,80),VAL=new Color(190,195,170),GOOD=new Color(80,180,50),WARN=new Color(220,170,30),CRIT=new Color(220,50,40),DIM=new Color(30,35,25)};}static ThemeColors ThemeHighContrast(){return new ThemeColors{BG=new Color(0,0,0),HDR=new Color(255,255,255),LBL=new Color(200,200,200),VAL=new Color(255,255,255),GOOD=new Color(0,255,0),WARN=new Color(255,255,0),CRIT=new Color(255,0,0),DIM=new Color(60,60,60)};}static ThemeColors ThemeMinimal(){return new ThemeColors{BG=new Color(15,15,20),HDR=new Color(160,165,175),LBL=new Color(120,125,135),VAL=new Color(180,180,190),GOOD=new Color(100,200,120),WARN=new Color(220,180,60),CRIT=new Color(220,70,60),DIM=new Color(40,42,48)};}static ThemeColors ThemePM(){return new ThemeColors{BG=new Color(0,0,0),HDR=new Color(100,200,255),LBL=new Color(255,200,50),VAL=new Color(200,200,200),GOOD=new Color(80,220,80),WARN=new Color(255,170,0),CRIT=new Color(255,60,60),DIM=new Color(55,55,65)};}
struct DisplayLine{public string Text;public string RightText;public Color Col;public Color DotCol;public bool IsSep;public bool IsBanner;public DisplayLine(string text,Color col,string rightText=""){Text=text;Col=col;RightText=rightText;DotCol=default(Color);IsSep=false;IsBanner=false;}}class DisplayGroup{public string Tag;public string[]Sections;public List<IMyTextSurface>Panels=new List<IMyTextSurface>();}List<DisplayLine>_displayLines=new List<DisplayLine>();List<DisplayGroup>_displayGroups=new List<DisplayGroup>();ThemeColors _theme;string _themeName="pm";int _renderGroupIdx=0;int _renderTick=0;void DL(string text,Color col){_displayLines.Add(new DisplayLine(text,col));}void DLR(string text,Color col,string right){_displayLines.Add(new DisplayLine(text,col,right));}void DLDot(string text,Color col,Color dot,string right=""){_displayLines.Add(new DisplayLine(text,col,right){DotCol=dot});}void DLSep(){_displayLines.Add(new DisplayLine("",_theme.VAL){IsSep=true});}void DLBanner(string title,string subtitle){_displayLines.Add(new DisplayLine(title,_theme.HDR,subtitle){IsBanner=true});}static MySprite Txt(string s,Vector2 pos,Color col,float scale,TextAlignment align=TextAlignment.LEFT)=>new MySprite(SpriteType.TEXT,s,pos,null,col,"Monospace",align,scale);static MySprite Rect(Vector2 center,Vector2 size,Color col)=>new MySprite(SpriteType.TEXTURE,"SquareSimple",center,size,col);static Color SaltColor(Color c,int a)=>new Color(c.R,c.G,c.B,(byte)Math.Min(a,c.A));Dictionary<string,int>pmv4Inventory=new Dictionary<string,int>();Dictionary<string,int>pmv4Surplus=new Dictionary<string,int>();bool pmv4Connected=false;int pmv4StaleCounter=0;const int PMV4_STALE_TICKS=36;List<string>samConnectors=new List<string>();List<long>samConnectorIds=new List<long>();Dictionary<string,string>homeConnectorReservations=new Dictionary<string,string>();long myGridEntityId=0;Dictionary<string,DroneInfo>availableDrones=new Dictionary<string,DroneInfo>();const int DRONE_STALE_TICKS=120;List<ActiveMission>activeMissions=new List<ActiveMission>();string loadingGridName="";string unloadingGridName="";class RecentReject{public string OrderStationId;public string Reason;public int Tick;}List<RecentReject>recentRejects=new List<RecentReject>();const int RECENT_REJECTS_MAX=5;const int RECENT_REJECTS_TTL_TICKS=360;int currentTick=0;int statusBroadcastCounter=0;bool dispatchHold=false;bool validationFailed=false;List<string>validationErrors=new List<string>();IMyProgrammableBlock pmv4PB=null;IMyBroadcastListener pmv4InvListener;IMyBroadcastListener pmv4CargoStatusListener;IMyBroadcastListener exchangeReqListener;IMyBroadcastListener droneAvailableListener;IMyBroadcastListener droneArrivedListener;IMyBroadcastListener droneNackListener;IMyBroadcastListener samListener;public Program(){if(string.IsNullOrWhiteSpace(Me.CustomData)){Me.CustomData=GetDefaultConfig();Echo("=== FIRST-TIME SETUP ===");Echo("Edit CustomData and recompile.");Runtime.UpdateFrequency=UpdateFrequency.None;return;}LoadConfig();FindPMV4();RunValidation();pmv4InvListener=IGC.RegisterBroadcastListener(CH_PMV4_INV);pmv4InvListener.SetMessageCallback("IGC");pmv4CargoStatusListener=IGC.RegisterBroadcastListener(CH_PMV4_STAT);pmv4CargoStatusListener.SetMessageCallback("IGC");exchangeReqListener=IGC.RegisterBroadcastListener(CH_EXCHANGE_REQ);exchangeReqListener.SetMessageCallback("IGC");droneAvailableListener=IGC.RegisterBroadcastListener(CH_DRONE_AVAILABLE);droneAvailableListener.SetMessageCallback("IGC");droneArrivedListener=IGC.RegisterBroadcastListener(CH_DRONE_ARRIVED);droneArrivedListener.SetMessageCallback("IGC");droneNackListener=IGC.RegisterBroadcastListener(CH_DRONE_NACK);droneNackListener.SetMessageCallback("IGC");samListener=IGC.RegisterBroadcastListener(CH_SAM);samListener.SetMessageCallback(CH_SAM);myGridEntityId=Me.CubeGrid.EntityId;ScanDisplayPanels();ScanOwnOres();Runtime.UpdateFrequency=UpdateFrequency.Update100;RecoverState();}public void Save(){PersistState();}public void Main(string argument,UpdateType updateSource){bool isUpdate100=(updateSource&UpdateType.Update100)!=0;
if(!string.IsNullOrEmpty(argument)){string arg=argument.Trim().ToUpperInvariant();if(arg=="RESET"){Storage="";activeMissions.Clear();homeConnectorReservations.Clear();loadingGridName="";unloadingGridName="";dispatchHold=false;Echo("State cleared.");}else if(arg=="RELOAD"){LoadConfig();FindPMV4();ScanDisplayPanels();ScanOwnOres();RunValidation();}else if(arg=="HOLD"){dispatchHold=true;PersistState();Echo("Dispatch HOLD: no new missions until RESUME.");}else if(arg=="RESUME"){dispatchHold=false;PersistState();Echo("Dispatch resumed.");}}if(validationFailed){foreach(var err in validationErrors)Echo(err);Echo("Fix errors and recompile.");return;}ProcessPMV4Data();ProcessPMV4CargoStatus();ProcessExchangeRequests();ProcessSAMBroadcasts();ProcessDroneAvailability();ProcessDroneArrived();ProcessDroneNacks();if(isUpdate100){currentTick++;CleanupStaleDrones();ExpireRecentRejects();CheckReturningDrones();oreScanCounter++;if(oreScanCounter>=ORE_SCAN_INTERVAL_TICKS){oreScanCounter=0;ScanOwnOres();}pmv4StaleCounter++;if(pmv4StaleCounter>PMV4_STALE_TICKS)pmv4Connected=false;statusBroadcastCounter++;if(statusBroadcastCounter>=18){statusBroadcastCounter=0;BroadcastStationStatus();}panelRescanCounter++;if(panelRescanCounter>=PANEL_RESCAN_INTERVAL_TICKS){panelRescanCounter=0;ScanDisplayPanels();}RenderDisplays();Echo($"SupplyStation v{VERSION} | {stationId}");if(dispatchHold)Echo("*** DISPATCH HOLD -- run RESUME to dispatch ***");Echo($"PMV4: {(pmv4Connected ? "Connected" : "Disconnected")} | Mode: {exchangeMode}");Echo($"Drones: {availableDrones.Count} | Missions: {activeMissions.Count}");Echo($"SAM connectors: {samConnectors.Count} | Home reserved: {homeConnectorReservations.Count}");Echo($"Loading: {(loadingGridName.Length > 0 ? loadingGridName : "none")}");Echo($"Unloading: {(unloadingGridName.Length > 0 ? unloadingGridName : "none")}");foreach(var m in activeMissions)Echo($"  Mission: {m.OrderStationId} [{m.State}] drone={m.DroneId}");}}void FindPMV4(){pmv4PB=null;var pbs=new List<IMyProgrammableBlock>();GridTerminalSystem.GetBlocksOfType(pbs,pb=>pb.CubeGrid==Me.CubeGrid&&pb.CustomData.Contains("[ProductionManagementv3]"));if(pbs.Count>0)pmv4PB=pbs[0];DiscoverContainerTags();}void DiscoverContainerTags(){string ssOreTag="",ssMixedTag="";var ssIni=new MyIni();if(ssIni.TryParse(Me.CustomData)){ssOreTag=ssIni.Get("SupplyStation","OreIngotTag").ToString("").Trim();ssMixedTag=ssIni.Get("SupplyStation","MixedTag").ToString("").Trim();}string pmOreTag="[PMO]",pmMixedTag="[PMX]";if(pmv4PB!=null){var pmIni=new MyIni();if(pmIni.TryParse(pmv4PB.CustomData)){pmOreTag=pmIni.Get("ProductionManagementv3","OreIngotTag").ToString("[PMO]");pmMixedTag=pmIni.Get("ProductionManagementv3","MixedTag").ToString("[PMX]");}}oreIngotTag=!string.IsNullOrEmpty(ssOreTag)?ssOreTag:pmOreTag;mixedTag=!string.IsNullOrEmpty(ssMixedTag)?ssMixedTag:pmMixedTag;}void ScanOwnOres(){ownOreInventory.Clear();var containers=new List<IMyCargoContainer>();GridTerminalSystem.GetBlocksOfType(containers,c=>c.CubeGrid==Me.CubeGrid&&(c.CustomName.Contains(oreIngotTag)||c.CustomName.Contains(mixedTag)));var items=new List<MyInventoryItem>();foreach(var c in containers){var inv=c.GetInventory(0);if(inv==null)continue;items.Clear();inv.GetItems(items);foreach(var item in items){if(item.Type.TypeId!="MyObjectBuilder_Ore")continue;string key="Ore."+item.Type.SubtypeId;int current;ownOreInventory.TryGetValue(key,out current);ownOreInventory[key]=current+(int)item.Amount;}}}void ProcessPMV4Data(){string myGrid=Me.CubeGrid.EntityId.ToString();while(pmv4InvListener.HasPendingMessage){var msg=pmv4InvListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<2)continue;string type=parts[0];string gridId=parts[1];if(gridId!=myGrid)continue;Dictionary<string,int>target=null;if(type=="INVENTORY")target=pmv4Inventory;else if(type=="SURPLUS")target=pmv4Surplus;else continue;target.Clear();for(int i=2;i<parts.Length;i++){int ci=parts[i].IndexOf(':');if(ci<0)continue;
string item=parts[i].Substring(0,ci);int qty;if(int.TryParse(parts[i].Substring(ci+1),out qty))target[item]=qty;}pmv4Connected=true;pmv4StaleCounter=0;if(type=="INVENTORY"){var avail=exchangeMode=="warehouse"?pmv4Inventory:pmv4Surplus;var sb=new StringBuilder();sb.Append("SS_INVENTORY|").Append(stationId);foreach(var kv in avail){if(kv.Value>0)sb.Append('|').Append(kv.Key).Append(':').Append(kv.Value);}foreach(var kv in ownOreInventory){int reserve;oreReserves.TryGetValue(kv.Key,out reserve);int shippable=kv.Value-reserve;if(shippable>0)sb.Append('|').Append(kv.Key).Append(':').Append(shippable);}IGC.SendBroadcastMessage(CH_SS_INVENTORY,sb.ToString());}}}void ProcessDroneAvailability(){while(droneAvailableListener.HasPendingMessage){var msg=droneAvailableListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<6||parts[0]!="AVAILABLE")continue;string droneId=parts[1];string homeStation=parts[2];if(homeStation!=stationId)continue;DroneInfo drone;if(!availableDrones.TryGetValue(droneId,out drone)){drone=new DroneInfo();drone.DroneId=droneId;availableDrones[droneId]=drone;}drone.HomeStation=homeStation;drone.CurrentStation=parts[3];drone.Tags.Clear();if(!string.IsNullOrEmpty(parts[4])){foreach(var t in parts[4].Split(',')){string tag=t.Trim().ToUpperInvariant();if(tag.Length>0)drone.Tags.Add(tag);}}double cap;if(double.TryParse(parts[5],out cap))drone.CargoCapacityL=cap;drone.GridName=parts.Length>=7?parts[6]:drone.DroneId;drone.LastSeenTick=currentTick;}}void ExpireRecentRejects(){for(int i=recentRejects.Count-1;i>=0;i--){if(currentTick-recentRejects[i].Tick>RECENT_REJECTS_TTL_TICKS)recentRejects.RemoveAt(i);}}void CleanupStaleDrones(){var stale=new List<string>();foreach(var kv in availableDrones){if(currentTick-kv.Value.LastSeenTick>DRONE_STALE_TICKS){bool onMission=false;foreach(var m in activeMissions){if(m.DroneId==kv.Key){onMission=true;break;}}if(!onMission)stale.Add(kv.Key);}}foreach(var id in stale)availableDrones.Remove(id);}void ProcessSAMBroadcasts(){while(samListener.HasPendingMessage){var msg=samListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var q=new Queue<string>(d.Split(new[]{"\n"},StringSplitOptions.None));if(q.Count<5)continue;string version=q.Dequeue();bool isV2V=version=="SAMv2V";if(!isV2V&&version!="SAMv2")continue;if(isV2V)q.Dequeue();long gridId;if(!long.TryParse(q.Dequeue(),out gridId))continue;if(gridId!=myGridEntityId)continue;string stationName=q.Dequeue();if(!isV2V)q.Dequeue();int connCount;if(!int.TryParse(q.Dequeue(),out connCount))continue;samConnectors.Clear();samConnectorIds.Clear();for(int i=0;i<connCount&&q.Count>=2;i++){long connId;long.TryParse(q.Dequeue(),out connId);string connName=q.Dequeue();if(connName.Contains("|H"))connName=connName.Replace("|H","");samConnectors.Add(connName);samConnectorIds.Add(connId);for(int s=0;s<9&&q.Count>0;s++)q.Dequeue();if(isV2V&&q.Count>0)q.Dequeue();int guideCount;if(q.Count>0&&int.TryParse(q.Peek(),out guideCount)){q.Dequeue();for(int g=0;g<guideCount;g++)for(int s=0;s<6&&q.Count>0;s++)q.Dequeue();}}}}string PickAvailableHomeConnector(string dispatchingDroneGrid){for(int i=0;i<samConnectors.Count;i++){string name=samConnectors[i];if(homeConnectorReservations.ContainsKey(name))continue;var block=GridTerminalSystem.GetBlockWithId(samConnectorIds[i])as IMyShipConnector;if(block==null)continue;if(block.Status==MyShipConnectorStatus.Connected){var other=block.OtherConnector;bool isOurDrone=other!=null&&!string.IsNullOrEmpty(dispatchingDroneGrid)&&other.CubeGrid.CustomName==dispatchingDroneGrid;if(!isOurDrone)continue;}return name;}return"";}void ReserveHomeConnector(string connectorName,string droneId){if(!string.IsNullOrEmpty(connectorName))homeConnectorReservations[connectorName]=droneId;}void ReleaseHomeConnector(string connectorName){if(!string.IsNullOrEmpty(connectorName))homeConnectorReservations.Remove(connectorName);}void ProcessExchangeRequests(){while(exchangeReqListener.HasPendingMessage){var msg=exchangeReqListener.AcceptMessage();
var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');if(parts.Length<6||parts[0]!="EXCHANGE_REQUEST")continue;string orderStationId=parts[1];string targetSupply=parts[2];if(targetSupply!=stationId)continue;if(dispatchHold){Reject(orderStationId,"system on hold");continue;}bool alreadyActive=false;foreach(var m in activeMissions){if(m.OrderStationId==orderStationId){alreadyActive=true;break;}}if(alreadyActive){Reject(orderStationId,"drone returning");continue;}if(loadingGridName.Length>0){Reject(orderStationId,"SS busy loading");continue;}Vector3D gps=ParseGPS(parts[3]);var wantItems=ParseItemList(parts[4]);var offerItems=ParseItemList(parts[5]);var stock=exchangeMode=="warehouse"?pmv4Inventory:pmv4Surplus;var canSend=new Dictionary<string,int>();foreach(var kv in wantItems){int available=0;if(kv.Key.StartsWith("Ore.")){int total;ownOreInventory.TryGetValue(kv.Key,out total);int reserve;oreReserves.TryGetValue(kv.Key,out reserve);available=Math.Max(0,total-reserve);}else{stock.TryGetValue(kv.Key,out available);}if(available>0)canSend[kv.Key]=Math.Min(kv.Value,available);}if(canSend.Count==0&&offerItems.Count==0){Reject(orderStationId,"no matching stock");continue;}var orderLocTags=new List<string>();if(parts.Length>=9&&!string.IsNullOrEmpty(parts[8])){foreach(var t in parts[8].Split(',')){string tag=t.Trim().ToUpperInvariant();if(tag.Length>0)orderLocTags.Add(tag);}}DroneInfo bestDrone=null;foreach(var kv in availableDrones){var drone=kv.Value;if(drone.CurrentStation!=stationId)continue;bool onMission=false;foreach(var m in activeMissions){if(m.DroneId==drone.DroneId){onMission=true;break;}}if(onMission)continue;string reason;if(!CanDroneDeliverTo(drone,orderStationId,orderLocTags,out reason))continue;if(bestDrone==null||drone.CargoCapacityL>bestDrone.CargoCapacityL)bestDrone=drone;}if(bestDrone==null){Reject(orderStationId,"no drone available");continue;}canSend=FairFillToCapacity(canSend,bestDrone.CargoCapacityL*droneFillFactor);if(canSend.Count==0&&offerItems.Count==0){Reject(orderStationId,"drone hold too small");continue;}string destConnector=parts.Length>=8?parts[7]:orderStationId;string homeConn=PickAvailableHomeConnector(bestDrone.GridName);if(string.IsNullOrEmpty(homeConn)){Reject(orderStationId,"no home connector");continue;}var mission=new ActiveMission();mission.OrderStationId=orderStationId;mission.DroneId=bestDrone.DroneId;mission.DroneGridName=bestDrone.GridName;mission.Destination=destConnector;mission.HomeConnector=homeConn;mission.DestinationGPS=gps;mission.WillBring=canSend;mission.WillCollect=offerItems;mission.State=MS_LOADING;mission.DispatchTick=currentTick;ReserveHomeConnector(homeConn,bestDrone.DroneId);string manifest=FormatItemList(canSend);string droneGridName=bestDrone.GridName;if(string.IsNullOrEmpty(droneGridName))continue;mission.DroneGridName=droneGridName;loadingGridName=droneGridName;IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PUSH|{droneGridName}|{manifest}");activeMissions.Add(mission);PersistState();break;}}void Reject(string orderStationId,string reason){IGC.SendBroadcastMessage(CH_EXCHANGE_REJ,$"EXCHANGE_REJECTED|{orderStationId}|{reason}");for(int i=recentRejects.Count-1;i>=0;i--){if(recentRejects[i].OrderStationId==orderStationId)recentRejects.RemoveAt(i);}recentRejects.Insert(0,new RecentReject{OrderStationId=orderStationId,Reason=reason,Tick=currentTick});while(recentRejects.Count>RECENT_REJECTS_MAX)recentRejects.RemoveAt(recentRejects.Count-1);}bool CanDroneDeliverTo(DroneInfo drone,string destination,List<string>orderLocTags,out string reason){reason="";if(orderLocTags==null||orderLocTags.Count==0)return true;foreach(var req in orderLocTags){bool found=false;foreach(var tag in drone.Tags){if(tag==req){found=true;break;}}if(!found){reason="Missing location tag: "+req;return false;}}return true;}void ProcessPMV4CargoStatus(){while(pmv4CargoStatusListener.HasPendingMessage){var msg=pmv4CargoStatusListener.AcceptMessage();var d=msg.Data as string;if(d==null)continue;var parts=d.Split('|');
if(parts.Length<2)continue;string cmd=parts[0];string gridName=parts[1];if(cmd=="PUSH_COMPLETE"&&gridName==loadingGridName){ActiveMission mission=null;foreach(var m in activeMissions){if(m.DroneGridName==gridName&&m.State==MS_LOADING){mission=m;break;}}if(mission==null){loadingGridName="";continue;}if(parts.Length>=3){mission.WillBring=ParseItemList(parts[2]);}if(mission.WillBring.Count==0&&mission.WillCollect.Count==0){Reject(mission.OrderStationId,"load failed (nothing loaded)");ReleaseHomeConnector(mission.HomeConnector);activeMissions.Remove(mission);loadingGridName="";PersistState();continue;}double distance=Vector3D.Distance(Me.GetPosition(),mission.DestinationGPS);int etaSeconds=droneSpeedMS>0?(int)(distance/droneSpeedMS):999;string willBring=FormatItemList(mission.WillBring);string willCollect=FormatItemList(mission.WillCollect);DroneInfo drone;double droneCap=0;if(availableDrones.TryGetValue(mission.DroneId,out drone))droneCap=drone.CargoCapacityL;IGC.SendBroadcastMessage(CH_EXCHANGE_ACC,$"EXCHANGE_ACCEPTED|{mission.OrderStationId}|{stationId}|{mission.DroneId}|{willBring}|{willCollect}|{etaSeconds}|{droneCap:F0}");IGC.SendBroadcastMessage(CH_DRONE_ASSIGN,$"ASSIGN|{mission.DroneId}|{mission.Destination}|{mission.HomeConnector}");availableDrones.Remove(mission.DroneId);mission.State=MS_OUTBOUND;loadingGridName="";PersistState();}else if(cmd=="PULL_COMPLETE"&&gridName==unloadingGridName){IGC.SendBroadcastMessage(CH_PMV4_STAT,$"TRANSFER_COMPLETE|{gridName}");string completedOS="";for(int i=activeMissions.Count-1;i>=0;i--){if(activeMissions[i].DroneGridName==gridName&&activeMissions[i].State==MS_UNLOADING){completedOS=activeMissions[i].OrderStationId;ReleaseHomeConnector(activeMissions[i].HomeConnector);activeMissions.RemoveAt(i);break;}}if(!string.IsNullOrEmpty(completedOS))IGC.SendBroadcastMessage(CH_MISSION_COMPLETE,$"MISSION_COMPLETE|{completedOS}");unloadingGridName="";PersistState();}else if(cmd=="TRANSFER_COMPLETE"){foreach(var m in activeMissions){if(m.