var result=new Dictionary<string,int>();double remaining=budgetL;int left=keys.Count;foreach(var k in keys){double uv=unitVol[k];if(uv<=0){result[k]=items[k];left--;continue;}double share=remaining/left;double demandL=items[k]*uv;int amt=(int)(Math.Min(demandL,share)/uv);if(amt>items[k])amt=items[k];if(amt>0){result[k]=amt;remaining-=amt*uv;}left--;}return result;}Dictionary<string,int>ParseItemList(string data){var result=new Dictionary<string,int>();if(string.IsNullOrEmpty(data))return result;foreach(var entry in data.Split(',')){int ci=entry.IndexOf(':');if(ci<0)continue;string item=entry.Substring(0,ci);int qty;if(int.TryParse(entry.Substring(ci+1),out qty))result[item]=qty;}return result;}Vector3D ParseGPS(string gpsStr){var parts=gpsStr.Split(':');if(parts.Length>=3){double x,y,z;if(double.TryParse(parts[0],out x)&&double.TryParse(parts[1],out y)&&double.TryParse(parts[2],out z))return new Vector3D(x,y,z);}return Vector3D.Zero;}void PersistState(){var sb=new StringBuilder();foreach(var m in activeMissions){sb.Append("MISSION|");sb.Append(m.OrderStationId).Append('|');sb.Append(m.DroneId).Append('|');sb.Append(m.DroneGridName).Append('|');sb.Append(m.Destination).Append('|');sb.Append($"{m.DestinationGPS.X:F1}:{m.DestinationGPS.Y:F1}:{m.DestinationGPS.Z:F1}").Append('|');sb.Append(FormatItemList(m.WillBring)).Append('|');sb.Append(FormatItemList(m.WillCollect)).Append('|');sb.Append(m.State).Append('|');sb.Append(m.DispatchTick).Append('|');sb.Append(m.HomeConnector??"");sb.AppendLine();}if(loadingGridName.Length>0)sb.AppendLine($"LOADING|{loadingGridName}");if(unloadingGridName.Length>0)sb.AppendLine($"UNLOADING|{unloadingGridName}");if(dispatchHold)sb.AppendLine("HOLD");Storage=sb.ToString();}void RecoverState(){activeMissions.Clear();loadingGridName="";unloadingGridName="";if(string.IsNullOrEmpty(Storage))return;foreach(var line in Storage.Split('\n')){var trimmed=line.Trim();if(string.IsNullOrEmpty(trimmed))continue;var parts=trimmed.Split('|');if(parts[0]=="MISSION"&&parts.Length>=10){var m=new ActiveMission();m.OrderStationId=parts[1];m.DroneId=parts[2];m.DroneGridName=parts[3];m.Destination=parts[4];m.DestinationGPS=ParseGPS(parts[5]);m.WillBring=ParseItemList(parts[6]);m.WillCollect=ParseItemList(parts[7]);m.State=parts[8];int tick;int.TryParse(parts[9],out tick);m.DispatchTick=tick;m.HomeConnector=parts.Length>=11?parts[10]:"";if(!string.IsNullOrEmpty(m.HomeConnector))ReserveHomeConnector(m.HomeConnector,m.DroneId);activeMissions.Add(m);}else if(parts[0]=="LOADING"&&parts.Length>=2){loadingGridName=parts[1];foreach(var m in activeMissions){if(m.DroneGridName==loadingGridName&&m.State==MS_LOADING){string manifest=FormatItemList(m.WillBring);IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PUSH|{loadingGridName}|{manifest}");break;}}}else if(parts[0]=="UNLOADING"&&parts.Length>=2){unloadingGridName=parts[1];IGC.SendBroadcastMessage(CH_PMV4_CMD,$"PULL|{unloadingGridName}");}else if(parts[0]=="HOLD"){dispatchHold=true;}}}
